import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { useAppContext } from '../context/AppContext';
import { useAuth } from '../context/AuthContext';

const TITLES = {
  '/': 'Dashboard',
  '/proyectos': 'Proyectos',
  '/clientes': 'Clientes',
  '/recursos': 'Recursos Humanos',
  '/equipos': 'Equipos',
  '/kpis': 'KPIs & Analítica',
  '/reportes': 'Reportes',
};

export default function Topbar() {
  const { apiOnline } = useAppContext();
  const { user, logout } = useAuth();
  const location = useLocation();
  const navigate = useNavigate();

  const title = TITLES[location.pathname] || 'Innovatech';

  const handleRefresh = () => navigate(0);

  const handleLogout = () => {
    if (window.confirm('¿Cerrar sesión?')) logout();
  };

  return (
    <header className="topbar">
      <h1>{title}</h1>
      <div className="topbar-right">
        <span className={`badge-api${apiOnline ? '' : ' offline'}`}>
          <i className="bi bi-circle-fill" style={{ fontSize: '7px' }}></i>
          BFF :8080 {apiOnline ? 'OK' : 'ERR'}
        </span>

        <button className="btn-ghost" onClick={handleRefresh}>
          <i className="bi bi-arrow-clockwise"></i> Actualizar
        </button>

        {user && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <div style={{ textAlign: 'right', lineHeight: 1.3 }}>
              <div style={{ fontSize: '13px', fontWeight: 600 }}>{user.nombre}</div>
              <div style={{ fontSize: '11px', color: 'var(--muted)' }}>{user.rol}</div>
            </div>
            <div
              style={{
                width: '32px', height: '32px', borderRadius: '50%',
                background: 'linear-gradient(135deg, var(--accent), var(--accent2))',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                fontFamily: "'Syne', sans-serif", fontSize: '12px',
                fontWeight: 700, color: '#fff', flexShrink: 0,
              }}
            >
              {user.nombre.charAt(0)}
            </div>
            <button
              className="btn-danger-ghost"
              onClick={handleLogout}
              title="Cerrar sesión"
              style={{ padding: '6px 10px' }}
            >
              <i className="bi bi-box-arrow-right"></i>
            </button>
          </div>
        )}
      </div>
    </header>
  );
}
